const CACHE='lumen-wing-2.0.1';
const CORE=['./','./index.html','./style.css?v=lumen-2.0.1','./app.mjs?v=lumen-2.0.1','./touch.mjs?v=lumen-2.0.1','./model.mjs?v=lumen-2.0.1','./render.mjs?v=lumen-2.0.1','./audio.mjs?v=lumen-2.0.1','./storage.mjs?v=lumen-2.0.1','./catalog.mjs?v=lumen-2.0.1','./assets/mech-atlas-v2.webp?v=lumen-2.0.1','./assets/mech-atlas-v2.json?v=lumen-2.0.1','./icon.svg?v=lumen-2.0.1','./manifest.webmanifest?v=lumen-2.0.1'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&/^(lumen-wing-|margin-tide-|nocturne-eclipse-)/.test(k)).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.open(CACHE).then(c=>c.match('./index.html'))));return;}const url=new URL(e.request.url);if(url.searchParams.get('v')==='lumen-2.0.1'||/\.(svg|webmanifest)$/.test(url.pathname))e.respondWith(caches.open(CACHE).then(async c=>(await c.match(e.request))||fetch(e.request)));});
